private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    while (index < bb.limit()) {
        int b = bb.get(index++);
        if (b < 0) {
            // Invalid octet
            throw new IllegalArgumentException("Invalid octet: " + b);
        }
        if (b < 0x80) {
            // ASCII character
            sb.append((char) b);
        } else if (b < 0xC0) {
            // Invalid octet
            throw new IllegalArgumentException("Invalid octet: " + b);
        } else if (b < 0xE0) {
            // Two-byte sequence
            int b1 = bb.get(index++);
            if (b1 < 0x80 || b1 > 0xBF) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + b1);
            }
            sb.append((char) ((b & 0x1F) << 6 | b1 & 0x3F));
        } else if (b < 0xF0) {
            // Three-byte sequence
            int b1 = bb.get(index++);
            int b2 = bb.get(index++);
            if (b1 < 0x80 || b1 > 0xBF || b2 < 0x80 || b2 > 0xBF) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + b1 + " or " + b2);
            }
            sb.append((char) ((b & 0x0F) << 12 | (b1 & 0x3F) << 6 | b2 & 0x3F));
        } else {
            // Four-byte sequence
