            int b2 = bb.get(index++);
            int b3 = bb.get(index++);
            if (b1 < 0x80 || b1 > 0xBF || b2 < 0x80 || b2 > 0xBF || b3 < 0x80 || b3 > 0xBF) {
                // Invalid continuation octet
                throw new IllegalArgumentException("Invalid continuation octet: " + b1 + " or " + b2 + " or " + b3);
