private String replaceFormatSpecifiers(LoggingEvent event, List<String> formatSpecifiers) {
    // Step 1: Create a map of format specifiers and their corresponding values
    Map<String, String> formatSpecifierValues = new HashMap<>();
    for (String formatSpecifier : formatSpecifiers) {
        String value = event.getFormattedMessage(formatSpecifier);
        formatSpecifierValues.put(formatSpecifier, value);
    }

    // Step 2: Replace the format specifiers with their corresponding values
    String formattedString = event.getFormattedMessage();
    for (Map.Entry<String, String> entry : formatSpecifierValues.entrySet()) {
        String formatSpecifier = entry.getKey();
        String value = entry.getValue();
        formattedString = formattedString.replace(formatSpecifier, value);
    }

    return formattedString;
}
